using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Data;

public class ApplicationDbContext(DbContextOptions<ApplicationDbContext> options) : IdentityDbContext<ApplicationUser>(options)
{
    public DbSet<Shipment> Shipments => Set<Shipment>();

    protected override void OnModelCreating(ModelBuilder builder)
    {
        base.OnModelCreating(builder);

        builder.Entity<Shipment>(e =>
        {
            e.HasIndex(s => s.TrackingNumber).IsUnique();
        });
    }
}

﻿@page "/"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService
@inject NavigationManager Navigation

<PageTitle>ShipmentTracker - Track Your Shipment</PageTitle>

<div class="text-center my-5">
    <h1 class="display-4">📦 ShipmentTracker</h1>
    <p class="lead text-muted">Track your shipment in real time</p>
</div>

<div class="row justify-content-center">
    <div class="col-md-6">
        <div class="card shadow-sm">
            <div class="card-body p-4">
                <h5 class="card-title mb-3">Track a Shipment</h5>
                <div class="input-group">
                    <input type="text" class="form-control form-control-lg"
                           placeholder="Enter tracking number (e.g., TRK-1001)"
                           @bind="trackingNumber" @bind:event="oninput"
                           @onkeydown="HandleKeyDown" />
                    <button class="btn btn-primary btn-lg" @onclick="TrackShipment" disabled="@isLoading">
                        @if (isLoading)
                        {
                            <span class="spinner-border spinner-border-sm me-1"></span>
                        }
                        Track
                    </button>
                </div>
                @if (notFound)
                {
                    <div class="alert alert-warning mt-3 mb-0">
                        No shipment found with that tracking number. Please check and try again.
                    </div>
                }
            </div>
        </div>
    </div>
</div>

@if (shipment is not null)
{
    <div class="row justify-content-center mt-4">
        <div class="col-md-8">
            <div class="card shadow-sm">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <strong>@shipment.TrackingNumber</strong>
                    <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span>
                </div>
                <div class="card-body">
                    <div class="row">
                        <div class="col-md-6">
                            <p><strong>From:</strong> @shipment.Origin</p>
                            <p><strong>To:</strong> @shipment.Destination</p>
                            <p><strong>Sender:</strong> @shipment.SenderName</p>
                            <p><strong>Recipient:</strong> @shipment.RecipientName</p>
                        </div>
                        <div class="col-md-6">
                            <p><strong>Shipped:</strong> @shipment.ShippedDate.ToString("MMM dd, yyyy")</p>
                            <p><strong>Est. Delivery:</strong> @shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</p>
                            @if (shipment.ActualDelivery.HasValue)
                            {
                                <p><strong>Delivered:</strong> @shipment.ActualDelivery.Value.ToString("MMM dd, yyyy")</p>
                            }
                            <p><strong>Weight:</strong> @shipment.WeightKg.ToString("F1") kg</p>
                        </div>
                    </div>

                    <div class="mt-3">
                        <h6>Delivery Progress</h6>
                        <div class="progress" style="height: 24px;">
                            <div class="progress-bar @GetProgressBarClass(shipment.Status)"
                                 role="progressbar"
                                 style="width: @(GetProgressPercent(shipment.Status))%">
                                @shipment.Status
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    </div>
}

@code {
    private string trackingNumber = string.Empty;
    private Shipment? shipment;
    private bool notFound;
    private bool isLoading;

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter") await TrackShipment();
    }

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        isLoading = true;
        notFound = false;
        shipment = null;

        shipment = await ShipmentService.GetByTrackingNumberAsync(trackingNumber.Trim());
        notFound = shipment is null;
        isLoading = false;
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Exception => "bg-danger",
        _ => "bg-secondary"
    };

    private static string GetProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Exception => "bg-danger",
        ShipmentStatus.Delivered => "bg-success",
        _ => "bg-primary"
    };

    private static int GetProgressPercent(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 30,
        ShipmentStatus.InTransit => 55,
        ShipmentStatus.OutForDelivery => 80,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Exception => 50,
        _ => 0
    };
}

