@page "/shipments"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Dispatch Dashboard</PageTitle>

<h2 class="mb-4">📋 Dispatch Dashboard</h2>

<div class="row mb-3">
    <div class="col-md-4">
        <div class="input-group">
            <span class="input-group-text">🔍</span>
            <input type="text" class="form-control" placeholder="Search tracking #, destination, name..."
                   @bind="searchTerm" @bind:event="oninput" @onkeydown="HandleSearchKey" />
            <button class="btn btn-outline-secondary" @onclick="LoadShipments">Search</button>
        </div>
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="statusFilter" @bind:after="LoadShipments">
            <option value="">All Statuses</option>
            @foreach (var status in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@status">@status</option>
            }
        </select>
    </div>
    <div class="col-md-5 text-end">
        <span class="text-muted">@(shipments?.Count ?? 0) shipments</span>
    </div>
</div>

@if (isLoading)
{
    <div class="text-center p-5">
        <div class="spinner-border text-primary" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (shipments is not null)
{
    <div class="table-responsive">
        <table class="table table-hover align-middle">
            <thead class="table-light">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Recipient</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in shipments)
                {
                    <tr>
                        <td><strong>@s.TrackingNumber</strong></td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td>@s.RecipientName</td>
                        <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                        <td>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                        <td>
                            @if (s.Status != ShipmentStatus.Delivered)
                            {
                                <div class="btn-group btn-group-sm">
                                    @if (s.Status == ShipmentStatus.Pending)
                                    {
                                        <button class="btn btn-outline-info" @onclick="() => UpdateStatus(s, ShipmentStatus.PickedUp)"
                                                disabled="@updatingId.HasValue">Pick Up</button>
                                    }
                                    @if (s.Status == ShipmentStatus.PickedUp)
                                    {
                                        <button class="btn btn-outline-primary" @onclick="() => UpdateStatus(s, ShipmentStatus.InTransit)"
                                                disabled="@updatingId.HasValue">In Transit</button>
                                    }
                                    @if (s.Status == ShipmentStatus.InTransit)
                                    {
                                        <button class="btn btn-outline-warning" @onclick="() => UpdateStatus(s, ShipmentStatus.OutForDelivery)"
                                                disabled="@updatingId.HasValue">Out for Delivery</button>
                                    }
                                    @if (s.Status == ShipmentStatus.OutForDelivery)
                                    {
                                        <button class="btn btn-outline-success" @onclick="() => UpdateStatus(s, ShipmentStatus.Delivered)"
                                                disabled="@updatingId.HasValue">Mark Delivered</button>
                                    }
                                    @if (s.Status != ShipmentStatus.Exception)
                                    {
                                        <button class="btn btn-outline-danger" @onclick="() => UpdateStatus(s, ShipmentStatus.Exception)"
                                                disabled="@updatingId.HasValue">Exception</button>
                                    }
                                </div>
                                @if (updatingId == s.Id)
                                {
                                    <span class="spinner-border spinner-border-sm ms-2"></span>
                                }
                            }
                            else
                            {
                                <span class="text-muted">✅ Complete</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    private List<Shipment>? shipments;
    private string searchTerm = string.Empty;
    private string statusFilter = string.Empty;
    private bool isLoading = true;
    private int? updatingId;

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task HandleSearchKey(KeyboardEventArgs e)
    {
        if (e.Key == "Enter") await LoadShipments();
    }

    private async Task LoadShipments()
    {
        isLoading = true;
        shipments = await ShipmentService.GetShipmentsAsync(
            string.IsNullOrEmpty(statusFilter) ? null : statusFilter,
            string.IsNullOrEmpty(searchTerm) ? null : searchTerm);
        isLoading = false;
    }

    private async Task UpdateStatus(Shipment shipment, ShipmentStatus newStatus)
    {
        updatingId = shipment.Id;
        var updated = await ShipmentService.UpdateStatusAsync(shipment.Id, newStatus);
        shipment.Status = updated.Status;
        shipment.ActualDelivery = updated.ActualDelivery;
        updatingId = null;
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Exception => "bg-danger",
        _ => "bg-secondary"
    };
}

using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;
using Microsoft.EntityFrameworkCore;

namespace ShipmentTracker.Services;

public static class ShipmentEndpoints
{
    public static void MapShipmentApi(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments");

        group.MapGet("/", async (string? status, string? search, ApplicationDbContext db) =>
        {
            var query = db.Shipments.AsQueryable();

            if (!string.IsNullOrEmpty(status) && Enum.TryParse<ShipmentStatus>(status, out var statusEnum))
                query = query.Where(s => s.Status == statusEnum);

            if (!string.IsNullOrEmpty(search))
            {
                var term = search.ToLower();
                query = query.Where(s =>
                    s.TrackingNumber.ToLower().Contains(term) ||
                    s.Destination.ToLower().Contains(term) ||
                    s.RecipientName.ToLower().Contains(term) ||
                    s.SenderName.ToLower().Contains(term));
            }

            return Results.Ok(await query.OrderByDescending(s => s.ShippedDate).ToListAsync());
        }).RequireAuthorization();

        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
            return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
        });

        group.MapGet("/{id:int}", async (int id, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.FindAsync(id);
            return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
        }).RequireAuthorization();

        group.MapPut("/{id:int}/status", async (int id, ShipmentStatus newStatus, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null) return Results.NotFound();

            shipment.Status = newStatus;
            if (newStatus == ShipmentStatus.Delivered)
                shipment.ActualDelivery = DateTime.UtcNow;

            await db.SaveChangesAsync();
            return Results.Ok(shipment);
        }).RequireAuthorization();
    }
}

