using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;
using Microsoft.EntityFrameworkCore;

namespace ShipmentTracker.Services;

public static class ShipmentEndpoints
{
    public static void MapShipmentApi(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments");

        group.MapGet("/", async (string? status, string? search, ApplicationDbContext db) =>
        {
            var query = db.Shipments.AsQueryable();

            if (!string.IsNullOrEmpty(status) && Enum.TryParse<ShipmentStatus>(status, out var statusEnum))
                query = query.Where(s => s.Status == statusEnum);

            if (!string.IsNullOrEmpty(search))
            {
                var term = search.ToLower();
                query = query.Where(s =>
                    s.TrackingNumber.ToLower().Contains(term) ||
                    s.Destination.ToLower().Contains(term) ||
                    s.RecipientName.ToLower().Contains(term) ||
                    s.SenderName.ToLower().Contains(term));
            }

            return Results.Ok(await query.OrderByDescending(s => s.ShippedDate).ToListAsync());
        }).RequireAuthorization();

        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
            return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
        });

        group.MapGet("/{id:int}", async (int id, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.FindAsync(id);
            return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
        }).RequireAuthorization();

        group.MapPut("/{id:int}/status", async (int id, ShipmentStatus newStatus, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null) return Results.NotFound();

            shipment.Status = newStatus;
            if (newStatus == ShipmentStatus.Delivered)
                shipment.ActualDelivery = DateTime.UtcNow;

            await db.SaveChangesAsync();
            return Results.Ok(shipment);
        }).RequireAuthorization();
    }
}

